 assert.equal((await f.pg.query('SELECT count(*)::integer n FROM public.checkout_provider_inspections')).rows[0].n,1);assert.equal((await f.pg.query('SELECT count(*)::integer n FROM public.checkout_provider_object_bindings')).rows[0].n,3);assert.equal((await f.status()).received,'0.00');
